{
  "name": "垂直反射镜模拟组件",
  "name_en": "Vertical Mirror Simulator",
  "manufacturer": "",
  "description": "非物理软件组件，用于在实验控制中模拟双支撑/双千斤顶垂直反射镜的运动与几何换算。它支持原始执行量与派生镜面参数之间的转换，并可按派生目标参数进行设定，适合测试控制逻辑与坐标变换。",
  "description_en": "A non-physical software component that simulates a two-support/two-jack vertical mirror for experiment control. It converts between raw actuator values and derived mirror parameters, and allows the mirror state to be set using derived targets, making it useful for testing control logic and coordinate transforms.",
  "actions": [
    {
      "action_name": "auto-set",
      "description": "设置模拟垂直反射镜的派生目标参数。",
      "description_en": "Set the derived target parameters of the simulated vertical mirror."
    },
    {
      "action_name": "auto-raw_to_derived",
      "description": "将原始双千斤顶参数转换为派生镜面参数。",
      "description_en": "Convert raw two-jack values into derived mirror parameters."
    },
    {
      "action_name": "auto-derived_to_raw",
      "description": "将派生镜面参数转换为原始双千斤顶参数。",
      "description_en": "Convert derived mirror parameters into raw two-jack values."
    }
  ],
  "tag_hints": [
    "vertical mirror simulation",
    "two-jack transform",
    "mirror kinematics",
    "coordinate conversion",
    "movable optics model"
  ]
}

